import {SCENARIOS,PLAYERS} from './engine.js';
import {matchSession} from './match-session.js';
import {personalizedMatch} from './your-match-model.js';

const el=(tag,cls,text)=>{const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node;};
const words={
 en:{eyebrow:'BTR / YOUR MATCH',title:'The game, through your eyes.',sub:'The same evidence. A different front page for every fan.',team:'Your club',player:'Follow a player',lens:'Your lens',pace:'Highlight pace',detail:'Detail',fan:'For the fan',beginner:'New to football',math:'Show the math',analyst:'Tactical',playerMode:'Player focus',essential:'Essential',balanced:'Balanced',every:'Every event',quick:'Quick read',full:'Full evidence',top:'YOUR TOP MOMENT',noMoment:'Waiting for a completed event',replay:'Replay this event ↗',playerStory:'PLAYER STORY',recap:'YOUR RECAP',momentList:'YOUR MOMENTS',source:'Synthetic match · reached events only',watchTitle:'YOUR MATCH / LIVE LENS',watchButton:'Open your match ↗',watchWaiting:'Your first relevant moment appears when an event is completed.',both:'Both teams'},
 es:{eyebrow:'BTR / TU PARTIDO',title:'El partido, desde tu punto de vista.',sub:'La misma evidencia. Una portada distinta para cada aficionado.',team:'Tu club',player:'Sigue a un jugador',lens:'Tu enfoque',pace:'Ritmo de destacados',detail:'Detalle',fan:'Aficionado',beginner:'Nuevo en fútbol',math:'Las matemáticas',analyst:'Táctica',playerMode:'Jugador',essential:'Esencial',balanced:'Equilibrado',every:'Cada acción',quick:'Lectura rápida',full:'Evidencia completa',top:'TU MOMENTO PRINCIPAL',noMoment:'Esperando una acción completada',replay:'Repetir esta acción ↗',playerStory:'HISTORIA DEL JUGADOR',recap:'TU RESUMEN',momentList:'TUS MOMENTOS',source:'Partido sintético · solo acciones alcanzadas',watchTitle:'TU PARTIDO / EN DIRECTO',watchButton:'Abrir tu partido ↗',watchWaiting:'Tu primer momento relevante aparece cuando termina una acción.',both:'Ambos equipos'},
 pt:{eyebrow:'BTR / SUA PARTIDA',title:'O jogo, do seu jeito.',sub:'A mesma evidência. Uma página inicial diferente para cada torcedor.',team:'Seu clube',player:'Acompanhe um jogador',lens:'Seu olhar',pace:'Ritmo de destaques',detail:'Detalhe',fan:'Torcedor',beginner:'Novo no futebol',math:'Veja a matemática',analyst:'Tática',playerMode:'Jogador',essential:'Essencial',balanced:'Equilibrado',every:'Cada ação',quick:'Leitura rápida',full:'Evidência completa',top:'SEU MOMENTO PRINCIPAL',noMoment:'Aguardando uma ação concluída',replay:'Rever esta ação ↗',playerStory:'HISTÓRIA DO JOGADOR',recap:'SEU RESUMO',momentList:'SEUS MOMENTOS',source:'Partida sintética · apenas ações alcançadas',watchTitle:'SUA PARTIDA / AO VIVO',watchButton:'Abrir sua partida ↗',watchWaiting:'Seu primeiro momento relevante aparece quando uma ação termina.',both:'Ambas as equipes'}
};
const section=el('section','your-match');section.setAttribute('aria-label','Your personalized match');
const watch=el('section','your-match-watch');watch.setAttribute('aria-label','Personalized match highlight');
document.querySelector('#centre .centre-journey')?.after(section);
document.querySelector('#watch .match-actions')?.after(watch);
const persist=s=>{try{localStorage.setItem('btr-your-match-v1',JSON.stringify({insightPace:s.insightPace,insightDetail:s.insightDetail}));}catch{}};
const setProfile=patch=>{matchSession.set(patch,'your-match');const s=matchSession.get();try{localStorage.setItem('btr-preferences-v1',JSON.stringify({language:s.language,mode:s.mode,team:s.team,focus:s.focus}));}catch{}};
try{const saved=JSON.parse(localStorage.getItem('btr-your-match-v1')||'null');if(saved)matchSession.set({insightPace:saved.insightPace,insightDetail:saved.insightDetail},'your-match-restore');}catch{}
function select(label,value,options,onChange){const wrap=el('label','ym-select'),name=el('span','',label),input=el('select');input.setAttribute('aria-label',label);for(const [id,text]of options){const option=el('option','',text);option.value=String(id);input.append(option);}input.value=String(value);input.addEventListener('change',()=>onChange(input.value));wrap.append(name,input);return wrap;}
function segmented(label,selected,options,onChange){const wrap=el('div','ym-choice'),name=el('span','',label),group=el('div','ym-segments');group.setAttribute('role','group');group.setAttribute('aria-label',label);for(const [id,text]of options){const button=el('button','',text);button.type='button';button.setAttribute('aria-pressed',String(selected===id));button.addEventListener('click',()=>onChange(id));group.append(button);}wrap.append(name,group);return wrap;}
function replay(moment){if(!moment)return;matchSession.set({time:moment.time,source:'match'},'your-match-replay');document.getElementById('watch-nav').click();}
let lastKey='';
function render(state){const key=[state.source,state.scenario,Math.floor(state.time),state.language,state.mode,state.team,state.focus,state.insightPace,state.insightDetail,state.corrected].join('|');if(key===lastKey)return;lastKey=key;const s=SCENARIOS.find(item=>item.id===state.scenario)||SCENARIOS[0],l=words[state.language]||words.en,p=personalizedMatch(s,state.time,state),lead=p.moments[0];
 watch.hidden=state.source!=='match';
 if(state.source!=='match')return;
 section.replaceChildren();watch.replaceChildren();
 const heading=el('header','ym-header'),headingText=el('div');headingText.append(el('span','eyebrow',l.eyebrow),el('h2','',l.title),el('p','',l.sub));heading.append(headingText,el('span','ym-source',l.source));section.append(heading);
 const controls=el('div','ym-controls');
 controls.append(select(l.team,state.team,[['harbor','Harbor FC'],['north','Northbridge'],['neutral',l.both]],value=>setProfile({team:value})));
 controls.append(select(l.player,state.focus,PLAYERS.map(item=>[item.id,item.name]),value=>setProfile({focus:Number(value)})));
 controls.append(segmented(l.lens,state.mode,[['fan',l.fan],['beginner',l.beginner],['math',l.math],['analyst',l.analyst],['player',l.playerMode]],value=>setProfile({mode:value})));
 controls.append(segmented(l.pace,state.insightPace,[['essential',l.essential],['balanced',l.balanced],['every',l.every]],value=>{matchSession.set({insightPace:value},'your-match');persist(matchSession.get());}));
 controls.append(segmented(l.detail,state.insightDetail,[['quick',l.quick],['full',l.full]],value=>{matchSession.set({insightDetail:value},'your-match');persist(matchSession.get());}));
 section.append(controls);
 const stage=el('div','ym-stage'),spotlight=el('article','ym-spotlight');spotlight.append(el('span','ym-label',l.top),el('strong','ym-clock',lead?.clock||p.clock),el('h3','',lead?.title||l.noMoment),el('p','ym-action',lead?.action||p.waiting),el('p','ym-meaning',lead?.summary||''));
 if(lead){if(state.insightDetail==='full')spotlight.append(el('small','ym-proof',`${p.evidenceLabel} ${lead.id} · ${lead.measurements}`));const button=el('button','ym-replay',l.replay);button.addEventListener('click',()=>replay(lead));spotlight.append(button);}
 const playerCard=el('article','ym-player');playerCard.append(el('span','ym-label',l.playerStory),el('div','ym-player-id',`${p.selectedPlayer.name} · ${p.selectedPlayer.role}`));
 const stats=el('div','ym-player-stats');for(const [value,label]of [[p.player.involvements,p.playerLabels.involvements],[p.player.completedPasses,p.playerLabels.passes],[`${new Intl.NumberFormat(p.language,{maximumFractionDigits:1}).format(p.player.displacement_m)} m`,p.playerLabels.position]]){const metric=el('div');metric.append(el('b','',String(value)),el('small','',label));stats.append(metric);}playerCard.append(stats);
 if(p.player.noEvent)playerCard.append(el('p','ym-no-event',p.player.noEvent));
 stage.append(spotlight,playerCard);section.append(stage);
 const lower=el('div','ym-lower'),momentBox=el('div','ym-moments');momentBox.append(el('span','ym-label',l.momentList));
 for(const moment of p.moments){const button=el('button','ym-moment'),stamp=el('span','ym-moment-stamp',moment.clock),content=el('span','ym-moment-copy');content.append(el('b','',moment.action),el('small','',state.insightDetail==='full'?`${moment.summary} ${moment.measurements}`:moment.summary));button.append(stamp,content,el('span','ym-arrow','↗'));button.setAttribute('aria-label',`${l.replay} ${moment.clock} ${moment.action}`);button.addEventListener('click',()=>replay(moment));momentBox.append(button);}if(!p.moments.length)momentBox.append(el('p','ym-no-event',p.waiting));
 const recap=el('article','ym-recap');recap.append(el('span','ym-label',l.recap),el('small','',p.recapLabel),el('p','',p.recap));if(p.correction)recap.append(el('p','ym-correction',p.correction));recap.append(el('small','ym-limit',p.limit));lower.append(momentBox,recap);section.append(lower);
 const watchLead=el('div','ym-watch-copy');watchLead.append(el('span','ym-label',l.watchTitle),el('strong','',lead?.action||l.watchWaiting),el('small','',lead?.summary||`${p.selectedPlayer.name} · ${p.player.involvements} ${p.playerLabels.involvements}`));const open=el('button','',l.watchButton);open.addEventListener('click',()=>{document.getElementById('centre-nav').click();section.scrollIntoView({behavior:'smooth',block:'start'});});watch.append(watchLead,open);
}
matchSession.subscribe(render);render(matchSession.get());
